pe:'application/json'});document.getElementById('manifestLink').setAttribute('href',URL.createObjectURL(blob));}catch(e){console.warn('manifest/icon injection failed',e);} })();</script></head><body><div id="loader" class="loader"><div class="loader-ring"><div class="loader-ring-inner"></div></div><div class="loader-text">Awakening the Legacy...</div></div><header class="site-header"><div class="container header-inner"><div class="brand"><img id="siteLogo" src="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='128' height='128' viewBox='0 0 128 128'><defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='%23ffd966'/><stop offset='1' stop-color='%236a1b9a'/></linearGradient></defs><rect width='128' height='128' rx='20' fill='%230f0b16'/><circle cx='64' cy='44' r='28' fill='url(%23g)'/><text x='64' y='86' font-family='Inter, Arial, sans-serif' font-size='18' font-weight='700' text-anchor='middle' fill='%23ffffff'>Umu-Oyi</text></svg>" alt="Umu-Oyi Logo" class="logo"/><div class="brand-text"><h1 id="brandTitle">Umu-Oyi</h1><p class="sub" id="brandSub">Eternal Heritage of Umugwuanyi-Oyi · Amama Village · Ede-Oballa · Nsukka · Enugu</p></div></div><nav class="nav"><a href="#history" class="nav-link" id="navHistory">History</a><a href="#tree" class="nav-link" id="navTree">Family Tree</a><a href="#values" class="nav-link" id="navValues">Core Values</a><a href="#traditions" class="nav-link" id="navTraditions">Traditions</a><a href="#contact" class="nav-link" id="navContact">Contact</a><a href="/signing.html" id="signingBtn" class="cta">Secure Signing</a><a href="/signup.html" id="signupBtn" class="cta">Sign Up</a><button id="langToggle" class="lang">Igbo</button><button id="themeToggle" class="lang">Theme</button></nav></div></header><main><section class="hero"><div class="container hero-inner"><div class="hero-text"><h2 id="heroTitle">Umu-Oyi — Preserving Our Royal Legacy</h2><p id="heroDesc">Embark on a journey through the illustrious history of the Umugwuanyi-Oyi family, rooted in Amama village with origins in Ede-Oballa. This platform honors our ancestors, unites generations, and safeguards our stories for eternity. Explore public heritage here; delve into personal archives securely within.</p><div class="hero-actions"><a href="#tree" id="btnDiscover" class="btn">Discover Family Tree</a><a href="#history" id="btnUncover" class="ghost">Uncover History</a></div></div><div class="hero-art"><div class="royal-crest"><svg viewBox="0 0 300 300" class="crest-svg"><defs><linearGradient id="crestGrad" x1="0" x2="1" y1="0" y2="1"><stop offset="0%" stop-color="#ffd966"/><stop offset="100%" stop-color="#6a1b9a"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="3" result="coloredBlur"/><feMerge><feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><circle cx="150" cy="150" r="120" fill="url(#crestGrad)" filter="url(#glow)"/><text x="150" y="160" text-anchor="middle" font-size="28" fill="#ffffff" font-family="serif" font-weight="bold">Umu-Oyi</text></svg></div></div></div><div class="hero-bg-animation"></div></section><section id="history" class="container history-section"><h3 id="historyTitle">Our Storied History</h3><p id="historyDesc">The Umugwuanyi-Oyi family traces its origins to the great Areji Amoke, founder of Amama village in Nsukka, Enugu State, with roots in Ede-Oballa. From two sons—Ezeokegbe and Onazi Oyi—sprang a lineage of strength, wisdom, and unity.</p><div class="history-timeline"><div class="timeline-item"><div class="timeline-dot"></div><div class="timeline-content"><h4 id="timelineFound">Founding Era</h4><p id="timelineFoundDesc">Areji Amoke establishes Amama, birthing Ezeokegbe and Onazi Oyi.</p></div></div><div class="timeline-item"><div class="timeline-dot"></div><div class="timeline-content"><h4 id="timelineExpand">Expansion</h4><p id="timelineExpandDesc">Ezeokegbe fathers Ukwuma and Ugwuanyi; Onazi Oyi sires Ubogbu and Onyekwunna.</p></div></div><div class="timeline-item"><div class="timeline-dot"></div><div class="timeline-content"><h4 id="timelineModern">Modern Generations</h4><p id="timelineModernDesc">From Ugwuanyi Oyi to present-day descendants, our family thrives with leaders and visionaries.</p></div></div></div></section><section id="tree" class="container tree-section"><div class="tree-header"><h3 id="treeTitle">Interactive Family Tree — Ancestral Branches</h3><div class="tree-controls"><div class="controls-left"><input id="searchInput" type="search" placeholder="Search by name (e.g. Onah, Ezugwu)"/><select id="generationFilter"><option value="">All generations</option><option value="1">1 (Founders)</option><option value="2">2</option><option value="3">3</option><option value="4">4</option><option value="5">5</option><option value="6">6</option></select></div><div class="controls-right"><button id="resetBtn" class="ghost">Reset</button></div></div></div><div class="tree-wrap" id="treeWrap"><svg id="familySvg" role="img" aria-label="Family tree"></svg><div id="magTooltip" aria-hidden="true"></div><div id="pinchHint" aria-hidden="true"><div class="pinch-inner"><div class="hand-anim"><svg id="fingers" viewBox="0 0 120 80" width="120" height="80"><circle cx="36" cy="40" r="10" fill="rgba(255,255,255,0.9)"></circle><circle cx="84" cy="40" r="10" fill="rgba(255,255,255,0.9)"></circle><rect x="30" y="52" width="60" height="8" rx="4" fill="rgba(255,255,255,0.06)"></rect></svg></div><div class="pinch-text"><div class="title">Pinch to zoom</div><div class="desc">Use two fingers to zoom and drag with one finger to move.</div><div class="actions"><button id="pinchGotIt" class="btn">Got it</button><button id="pinchDontShow" class="ghost">Don't show again</button></div></div></div></div><div class="tree-note" id="treeNote">Expand branches to explore. For complete profiles, <a href="/signing.html" class="login-link">sign in</a>.</div></section><section id="values" class="container values-section"><h3 id="valuesTitle">Our Core Values</h3><div class="values-grid"><div class="value-card"><h4>Royalty</h4><p>Respect for lineage and leaders.</p></div><div class="value-card"><h4>Peace</h4><p>Harmony and calm in family life.</p></div><div class="value-card"><h4>Love</h4><p>Care across generations.</p></div><div class="value-card"><h4>Unity</h4><p>Strength in togetherness.</p></div><div class="value-card"><h4>Truth</h4><p>Accurate records and integrity.</p></div></div></section><section id="traditions" class="container traditions-section"><h3 id="traditionsTitle">Timeless Traditions</h3><div class="traditions-grid"><div class="tradition-item"><h4>Naming Ceremonies</h4><p>Welcoming newborns with blessings and ancestral names.</p></div><div class="tradition-item"><h4>Annual Reunions</h4><p>Gatherings in Amama to honor elders and share stories.</p></div><div class="tradition-item"><h4>Cultural Festivals</h4><p>Participating in Nsukka festivals like New Yam.</p></div></div></section><section id="contact" class="container contact-section"><h3 id="contactTitle">Connect With Us</h3><form class="contact-form" id="contactForm"><input id="contactName" type="text" placeholder="Your Name" required/><input id="contactEmail" type="email" placeholder="Your Email" required/><textarea id="contactMessage" placeholder="Your Message" required></textarea><button id="contactSend" type="submit" class="btn">Send Message</button></form></section><section class="container cta-footer"><div class="cta-inner"><h4 id="footerCta">Enter the Inner Sanctum</h4><p id="footerCtaDesc">Access detailed personal histories and contribute securely.</p><a id="footerLogin" href="/signing.html" class="btn">Proceed to Signing</a></div></section></main><footer class="site-footer"><div class="container footer-inner"><div>© <span id="year"></span> Umu-Oyi Family Heritage Archive · Built by Master Chukwuemeka Onah Henry</div><div class="foot-links"><a href="/privacy.html">Privacy Policy</a><a href="/terms.html">Terms 